function MeanAbsoluteDeviation(numbers: array of real): real;
begin
  var mean := numbers.Average;
  var mad := 0.0;

  foreach var num in numbers do
    mad += Abs(num - mean);

  Result := mad / numbers.Length;
end;


function Intersperse(numbers: array of integer; delimeter: integer): array of integer;
begin
  if numbers.Length = 0 then
  begin
    Result := new integer[0];
    exit;
  end;
  var resultList := new List<integer>;
  resultList.Add(numbers[0]);
  for var i := 1 to numbers.Length - 1 do
  begin
    resultList.Add(delimeter);
    resultList.Add(numbers[i]);
  end;
  Result := resultList.ToArray;
end;

