function ParseNestedParens(parenString: string): array of integer;
begin
  var stack := new Stack<integer>;
  var maxDepth := 0;
  var currentDepth := 0;
  var resultList := new List<integer>;
  foreach var ch in parenString do
  begin
    if ch = '(' then
    begin
      currentDepth += 1;
      if currentDepth > maxDepth then
        maxDepth := currentDepth;
      stack.Push(currentDepth);
    end
    else if ch = ')' then
    begin
      currentDepth -= 1;
      var lastOpen := stack.Pop;
      if lastOpen = maxDepth then
        resultList.Add(maxDepth)
      else
        resultList.Add(maxDepth - 1);
    end;
  end;
  Result := resultList.ToArray;
end;


