function SumProduct(numbers: array of integer): (integer, integer);
begin
  var sum := 0;
  var product := 1;
  foreach var num in numbers do
  begin
    sum += num;
    product *= num;
  end;
  Result := (sum, product);
end;

begin
  Println(SumProduct(|1, 2, 3, 4|)); // (10, 24)
  Println(SumProduct(|1|)); // (1, 1)
  Println(SumProduct(|1, 2, 3, 4, 5|)); // (15, 120)
end.


