function MakePalindrome(str: string): string;
begin
  var reversedStr := new string(str.Reverse.ToArray);
  var prefix := str;
  var suffix := reversedStr;

  for var i := 1 to prefix.Length do
  begin
    if prefix.StartsWith(suffix) then
    begin
      Result := str + reversedStr.Substring(prefix.Length);
      exit;
    end;
    suffix := suffix.Substring(1);
  end;

  Result := str + reversedStr;
end;


function StringXor(a, b: string): string;
begin
  var minLen := Min(a.Length, b.Length);
  var res := '';
  for var i := 1 to minLen do
  begin
    if a[i] = b[i] then
      res += '0'
    else
      res += '1';
  end;
  Result := res + a.Substring(minLen) + b.Substring(minLen);
end;


