function ParseMusic(musicString: string): array of integer;
begin
  var notes := musicString.Split;
  var beatCount := new List<integer>;
  var noteSymbols := new List<char>;
  var beat := 1;
  var lastSymbol := #0;

  foreach var note in notes do
  begin
    var noteChars := note.ToCharArray;
    for var i := 0 to noteChars.Length - 1 do
    begin
      var ch := noteChars[i];
      if (ch = 'o') and (lastSymbol <> 'o') then
      begin
        beatCount.Add(beat);
        noteSymbols.Add('o');
        if beat = 4 then
          beat := 1
        else
          beat += 1;
      end
      else if (ch = '.') and (lastSymbol = 'o') then
      begin
        beatCount.Add(beat);
        noteSymbols.Add('.|');
        beat += 1;
      end
      else if (ch = '|') and (lastSymbol = '.') then
      begin
        beatCount.Add(beat);
        noteSymbols.Add('|');
        beat += 1;
      end
      else if (ch = 'o') and (lastSymbol = '|') then
      begin
        beatCount.Add(beat);
        noteSymbols.Add('o|');
        beat += 1;
      end
      else if ch = ' ' then
        continue
      else
        raise new System.ArgumentException('Invalid character in note string');
    end;
    lastSymbol := note[note.Length];
  end;

  Result := beatCount.ToArray;
end;


function HowManyTimes(str, substring: string): integer;
begin
  var count := 0;
  var start := 0;
  while start < str.Length do
  begin
    var pos := str.IndexOf(substring, start);
    if pos <> -1 then
    begin
      count += 1;
      start := pos + 1;
    end
    else
      break;
  end;
  Result := count;
end;


