function Factorize(n: integer): array of integer;
begin
  var i := 2;
  var num := n;
  var factors := new List<integer>;

  while i * i <= num do
  begin
    if num mod i = 0 then
    begin
      factors.Add(i);
      num := num div i;
    end
    else
      i := i + 1;
  end;

  if num > 1 then
    factors.Add(num);

  Result := factors.ToArray;
end;


function RemoveDuplicates(numbers: array of integer): array of integer;
begin
  var seen := new HashSet<integer>;
  var seen2 := new HashSet<integer>;
  var list := new List<integer>;

  foreach var num in numbers do
  begin
    if not seen.Contains(num) then
    begin
      seen.Add(num);
      list.Add(num);
    end
    else if not seen2.Contains(num) then
    begin
      seen2.Add(num);
      list.Add(num);
    end;
  end;

  Result := list.ToArray;
end;


