function SortThird(l: array of integer): array of integer;
begin
  var thirdIndices := new List<integer>;
  for var i := 0 to l.Length - 1 do
    if i mod 3 = 0 then
      thirdIndices.Add(i);

  var thirdValues := new List<integer>;
  for var i := 0 to thirdIndices.Count - 1 do
    thirdValues.Add(l[thirdIndices[i]]);

  thirdValues.Sort;

  var res := new List<integer>;
  var thirdIndex := 0;

  for var i := 0 to l.Length - 1 do
  begin
    if i mod 3 = 0 then
    begin
      res.Add(thirdValues[thirdIndex]);
      thirdIndex += 1;
    end
    else
      res.Add(l[i]);
  end;

  Result := res.ToArray;
end;


