  end;
end;


function TriplesSumToZero(l: array of integer): boolean;
begin
  var sorted := l.ToArray;
  sorted.Sort;

  if (sorted.Length < 3) or (sorted[0] > 0) then
  begin
    Result := False;
    exit;
  end;

  for var i := 0 to sorted.Length - 3 do
  begin
    if (i > 0) and (sorted[i] = sorted[i-1]) then
      continue;

    var left := i + 1;
    var right := sorted.Length - 1;

    while left < right do
    begin
      var sum := sorted[i] + sorted[left] + sorted[right];

      if sum = 0 then
      begin
        Result := True;
        exit;
      end
      else if sum < 0 then
        left += 1
      else
        right -= 1;

      if (left > i + 1) and (sorted[left] = sorted[left-1]) then
        left += 1
      else if (right < sorted.Length - 1) and (sorted[right] = sorted[right+1]) then
        right -= 1;
    end;
  end;

  Result := False;
end;


