function ChangeBase(x: integer; base: integer): string;
begin
  if not (base in 2..36) then
    raise new System.ArgumentOutOfRangeException('base', base, 'Base is out of range. It must be in [2..36]');
  var sb := new System.Text.StringBuilder('');
  while x > 0 do
  begin
    sb.Insert(0, char(x mod base + ord('0')));
    x := x div base
  end;
  Result := if sb.Length = 0 then '0'
    else sb.ToString
end;


