function Median(l: array of integer): real;
begin
  var n := l.Length;
  var sorted := l.ToArray;
  sorted.Sort;
  if n = 0 then
    Result := 0
  else
  begin
    if n mod 2 = 0 then
      Result := (sorted[n div 2 - 1] + sorted[n div 2]) / 2
    else
      Result := sorted[n div 2];
  end;
end;


