function SameChars(s0, s1: string): boolean;
begin
  var d0 := new Dictionary<char, integer>;
  var d1 := new Dictionary<char, integer>;

  foreach var ch in s0 do
    if d0.ContainsKey(ch) then
      d0[ch] += 1
    else
      d0[ch] := 1;

  foreach var ch in s1 do
    if d1.ContainsKey(ch) then
      d1[ch] += 1
    else
      d1[ch] := 1;

  Result := d0.Keys.ToHashSet.SetEquals(d1.Keys.ToHashSet);
end;


