function Derivative(xs: array of real): array of real;
begin
  var n := xs.Length;
  if n <= 1 then
  begin
    Result := new real[0];
    exit;
  end;
  var res := new real[n - 1];
  for var i := 1 to n - 1 do
    res[i - 1] := xs[i] * i;
  Result := res;
end;


function Fibfib(n: integer): integer;
begin
  if n = 0 then
    Result := 0
  else if n = 1 then
    Result := 0
  else if n = 2 then
    Result := 1
  else
  begin
    var fib := new integer[n + 1];
    fib[0] := 0;
    fib[1] := 0;
    fib[2] := 1;
    for var i := 3 to n do
      fib[i] := fib[i - 1] + fib[i - 2] + fib[i - 3];
    Result := fib[n];
  end;
end;


