function CircularShift(x: integer; shift: integer): string;
begin
  var digits := x.ToString.ToCharArray.ToList;
  var n := digits.Count;
  shift := shift mod n;
  if shift < 0 then
    shift := n + shift;
  var reversed := digits.GetRange(n - shift, n).ConvertAll(d -> d.ToString)
    .Concat(digits.GetRange(0, n - shift)).ToList;
  Result := string.Join('', reversed);
end;


