  Result := m - (a + o);
end;


function Pluck(arr: array of integer): array of integer;
begin
  var smallestEven := integer.MaxValue;
  var smallestIndex := integer.MaxValue;
  var index := 0;

  for var i := 0 to arr.Length - 1 do
  begin
    if (arr[i] mod 2 = 0) and (arr[i] <>0) and (arr[i] <> smallestEven) then
    begin
      smallestEven := arr[i];
      smallestIndex := i;
    end;
    index += 1;
  end;

  if smallestEven = integer.MaxValue then
    Result := new integer[0];
  else
    Result := |smallestEven, smallestIndex|;
end;


function Search(lst: array of integer): integer;
begin
  var freq := new Dictionary<integer, integer>;
  foreach var num in lst do
    if freq.ContainsKey(num) then
      freq[num] += 1
    else
      freq[num] := 1;

  var res := -1;
  foreach var kv in freq.OrderByDescending(kv -> kv.Value) do
    if kv.Key > res then
      res := kv.Key;

  Result := res;
end;


function StrangeSortList(lst: array of integer): array of integer;
begin
  if lst.Length = 0 then
  begin
    Result := new integer[0];
    exit;
  end;

  var tempLst := lst.ToList;
  tempLst.Sort;
  var resultList := new List<integer>;

  while tempLst.Count > 0 do
  begin
    resultList.Add(tempLst[0]);
    tempLst.RemoveAt(0);

    if tempLst.Count > 0 then
    begin
      resultList.Add(tempLst[tempLst.Count - 1]);
      tempLst.RemoveAt(tempLst.Count - 1);
    end;
  end;

  Result := resultList.ToArray;
end;


function TriangleArea(a, b, c: real): real;
begin
  if (a + b > c) and (a + c > b) and (b + c > a) then
  begin
    var s := (a + b + c) / 2;
    var area := Sqrt(s * (s - a) * (s - b) * (s - c));
    Result := Round(area, 2);
  end
  else
    Result := -1;
end;


