function SmallestChange(arr: array of integer): integer;
begin
  var n := arr.Length;
  var changes := 0;
  var i := 0;
  var j := n - 1;

  while i < j do
  begin
    if arr[i] <> arr[j] then
      changes += 1;
    i += 1;
    j -= 1;
  end;

  Result := changes;
end;


