function IsMultiplyPrime(a: integer): boolean;
begin
  var primes := new List<integer>;
  var i := 2;
  while i * i <= a do
  begin
    if a mod i = 0 then
    begin
      primes.Add(i);
      a := a div i;
    end
    else
      i += 1;
  end;
  if a > 1 then
    primes.Add(a);

  var primeCount := primes.Count;
  if primeCount < 3 then
  begin
    Result := False;
    exit;
  end;

  var primeProduct := 1;
  for var j := 0 to primeCount - 1 do
    primeProduct := primeProduct * primes[j];

  Result := primeProduct = 3 * primes[0];
end;


