  begin
    if grade = 4.0 then
      letterGrades.Add('A+')
    else if grade > 3.7 then
      letterGrades.Add('A')
    else if grade > 3.3 then
      letterGrades.Add('A-')
    else if grade > 3.0 then
      letterGrades.Add('B+')
    else if grade > 2.7 then
      letterGrades.Add('B')
