function Encode(message: string): string;
begin
  var sb := new StringBuilder;
  foreach var ch in message do
  begin
    if ch.IsLetter then
    begin
      var lowerCh := Char.ToLower(ch);
      if lowerCh.Equals('a') then
        sb.Append('T')
      else if lowerCh.Equals('e') then
        sb.Append('G')
      else if lowerCh.Equals('i') then
        sb.Append('K')
      else if lowerCh.Equals('o') then
        sb.Append('Q')
      else if lowerCh.Equals('u') then
        sb.Append('W')
      else
      begin
        var alphabet := 'BCDFGHJKLMNPQRSTVWXYZbcdfghjklmnpqrstvwxyz';
        var count := 1;
        while count <= alphabet.Length do
        begin
          if alphabet[count] = lowerCh then
            break;
          count += 1;
        end;
        count += 1;
        sb.Append(alphabet[count]);
      end;
    end
    else
      sb.Append(ch);
  end;
  Result := sb.ToString;
end;


function IsPrime(n: integer): boolean;
begin
  if n <= 1 then
    Result := False
  else
  begin
    for var i := 2 to Round(Sqrt(n)) do
      if n mod i = 0 then
      begin
        Result := False;
        exit;
      end;
    Result := True;
  end;
end;

function SumOfDigits(n: integer): integer;
begin
  var sum := 0;
  var num := n;
  while num > 0 do
  begin
    sum += num mod 10;
    num := num div 10;
  end;
  Result := sum;
end;

function LargestPrimeSum(lst: array of integer): integer;
begin
  var maxPrime := 0;

  foreach var num in lst do
  begin
    if IsPrime(num) then
    begin
      var sumOfDigits := SumOfDigits(num);
      if sumOfDigits > maxPrime then
        maxPrime := sumOfDigits;
    end;
  end;

  Result := maxPrime;
end;


function CheckDictCase(dict: Dictionary<string, string>): boolean;
begin
  if dict.Count = 0 then
  begin
    Result := False;
    exit;
  end;

  var keys := dict.Keys.ToList;
  var firstKey := keys[0];
  var firstKeyLower := firstKey.ToLower;
  var firstKeyUpper := firstKey.ToUpper;

  var allLower := True;
  var allUpper := True;

  for var i := 0 to keys.Count - 1 do
  begin
    var key := keys[i];
    if key.ToLower <> firstKeyLower then
    begin
      allLower := False;
      break;
    end;
    if key.ToUpper <> firstKeyUpper then
    begin
      allUpper := False;
      break;
    end;
  end;

  Result := allLower or allUpper;
end;


