  while count < n do
  begin
    if IsPrime(num) then
    begin
      Result[count] := num;
      count += 1;
    end;
    num += 1;
  end;
end;


function Multiply(a, b: integer): integer;
begin
  var product := 0;
  var aNum := Abs(a);
  var bNum := Abs(b);

  for var i := 1 to bNum do
  begin
    product += aNum * (bNum - i + 1);
  end;

  Result := product;
end;


