function MakeAPile(n: integer): array of integer;
begin
  var stones := n;
  var pile := new List<integer>;
  pile.Add(stones);

  while True do
  begin
    if stones mod 2 = 0 then
      stones := stones + 1
    else
      stones := stones + 2;

    pile.Add(stones);

    if stones > 100 then
      break;
  end;

  Result := pile.ToArray;
end;


function WordsString(s: string): array of string;
begin
  var specials := ' ,.';
  var trimmed := s.Trim;
  if trimmed.Length = 0 then
  begin
    Result := new string[0];
    exit;
  end;

  var chars := trimmed.ToCharArray;
  var start := 1;
  var words := new List<string>;

  for var i := 1 to chars.Length do
  begin
    if specials.Contains(chars[i]) then
    begin
      if start <> i then
        words.Add(trimmed.Substring(start, i - start));
      start := i + 1;
    end;
  end;

  if start <= chars.Length then
    words.Add(trimmed.Substring(start-1));

  Result := words.ToArray;
end;


function ChooseNum(x, y: integer): integer;
begin
  var evenMax := -1;
  for var num := y downto x do
    if (num mod 2 = 0) and (num >= evenMax) then
      evenMax := num;
  Result := evenMax;
end;


function RoundedAvg(n, m: integer): string;
begin
  if n > m then
  begin
    Result := '-1';
    exit;
  end;

  var total := 0;
  for var i := n to m do
    total += i;

  var avg := Round(total / (m - n + 1));
  var binary := Convert.ToString(avg, 2);

  Result := '0b' + binary;
end;


function UniqueDigits(x: array of integer): array of integer;
begin
  var uniqueDigits := new List<integer>;

  foreach var num in x do
  begin
    var numStr := num.ToString;
    var hasEvenDigit := False;

    for var i := 1 to numStr.Length do
    begin
      if numStr[i] = '0' then
        continue;

      if (numStr[i] mod 2) <> 0 then
      begin
        hasEvenDigit := True;
        break;
      end;
    end;

    if not hasEvenDigit then
      uniqueDigits.Add(num);
  end;

  uniqueDigits.Sort;
  Result := uniqueDigits.ToArray;
end;


