function EvenOddPalindrome(n: integer): (integer, integer);
begin
  var evenPalindrome := 0;
  var oddPalindrome := 0;

  for var i := 1 to n do
  begin
    var isPalindrome := True;
    var num := i;

    // Check if it is palindrome
    while num > 0 do
    begin
      if num mod 10 <> (num div 10) mod 10 then
      begin
        isPalindrome := False;
        break;
      end;
      num := num div 10;
    end;

    if isPalindrome then
    begin
      if i mod 2 = 0 then
        evenPalindrome += 1
      else
        oddPalindrome += 1;
    end;
  end;

  Result := (evenPalindrome, oddPalindrome);
end;


