function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var m := grid.Length;
  var n := grid[0].Length;
  var filled := 0;
  var filledPerBucket := 0;
  var bucketCapacity := capacity;
  var wells := new List<integer>;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if grid[i][j] = 1 then
        wells.Add(i * n + j);

  wells.Sort;

  foreach var well in wells do
  begin
    var pos := well div n;
    var neg := well mod n;

    if (pos <> neg) and (pos <> -1) and (neg <> -1) then
    begin
      var bucketPos := pos div bucketCapacity;
      var bucketNeg := neg div bucketCapacity;

      if (bucketPos <> bucketNeg) and (bucketPos <> -1) and (bucketNeg <> -1) then
      begin
        filled := filled + 1;
        filledPerBucket := filledPerBucket + 1;
      end
      else
        filledPerBucket := filledPerBucket + 1;
      end;
  end;

  Result := filledPerBucket;
end;


