function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  var directions := |(0, 1), (1, 0), (0, -1), (-1, 0)|;
  var visited := new HashSet<(integer, integer)>;
  var minHeap := new List<(integer, integer, integer)>;
  minHeap.Add((grid[0][0], 0, 0));
  var ans := new List<integer>;
  var temp := new integer[k];

  while minHeap.Count > 0 do
  begin
    minHeap.Sort((x, y) -> x.Item1.CompareTo(y.Item1));
    var (value, x, y) := minHeap[0];
    minHeap.RemoveAt(0);

    if (ans.Count = k) then
    begin
      Result := ans.ToArray;
      exit;
    end;

    if (x = n - 1) and (y = n - 1) then
    begin
      ans.Add(value);
      continue;
    end;

    for var i := 0 to 3 do
    begin
      var dx := x + directions[i, 0];
      var dy := y + directions[i, 1];

      if (dx >= 0) and (dx < n) and (dy >= 0) and (dy < n) and 
         not visited.Contains((dx, dy)) then
      begin
        visited.Add((dx, dy));
        minHeap.Add((grid[dx][dy], dx, dy));
      end;
    end;
  end;

  Result := new integer[0];
end;


function Tri(n: integer): array of real;
