      trib.Add(i / 2)
    else
    begin
      var prev1 := trib[trib.Count - 1];
      var prev2 := trib[trib.Count - 2];
      trib.Add(prev1 + prev2 + (trib[trib.Count - 1] + 1));
    end;
  end;

  Result := trib.ToArray;
end;


