function IsNested(s: string): boolean;
begin
  var stack := new Stack<char>;

  for var i := 1 to s.Length do
  begin
    var ch := s[i];

    if ch = '[' then
      stack.Push(ch)
    else if ch = ']' then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;

      var top := stack.Pop;
      if top <> '[' then
      begin
        Result := False;
        exit;
      end;
    end;
  end;

  Result := stack.Count = 0;
end;


