  var k := n - 1;

  while (k >= 0) and (arr[k] >= arr[k - 1]) do
    k -= 1;

  if k = 0 then
    Result := -1
  else
  begin
    var l := n - 1;
    while (l > k) and (arr[l] >= arr[k]) do
      l -= 1;

    Result := l;
  end;
end;


