function IsEqualToSumEven(n: integer): boolean;
begin
  if n mod 2 <> 0 then
    Result := False
  else
  begin
    var a := 2;
    var b := 2;
    var c := 2;
    var d := n - 2;

    while b <= d do
    begin
      if (a + b + c = n) and (a + b = n - d) and (a + c = n - d - b) and (b + c = n - d - b - a) then
      begin
        Result := True;
        exit;
      end;
      c += 2;
      if c > d - b then
      begin
        c := d - b;
        b += 2;
      end;
      if b > d - a then
      begin
        b := d - a;
        a += 2;
      end;
    end;
    Result := False;
  end;
end;


