  var romanNum := '';
  var remaining := number;

  for var i := 0 to values.Length - 1 do
  begin
    while remaining >= values[i] do
    begin
      romanNum += symbols[i];
      remaining -= values[i];
    end;
  end;

  Result := romanNum.ToLower;
end;


function RightAngleTriangle(a, b, c: integer): boolean;
begin
  Result := (a * a + b * b = c * c) or (b * b + c * c = a * a) or (c * c + a * a = b * b);
end;


function FindMax(words: array of string): string;
begin
  var maxUnique := 0;
  var resultStr := '';

  foreach var word in words do
  begin
    var uniqueChars := new HashSet<char>(word.ToCharArray);
    var count := uniqueChars.Count;

    if count > maxUnique then
    begin
      maxUnique := count;
      resultStr := word;
    end;
  end;

  Result := resultStr;
end;


function Eat(number, need, remaining: integer): (integer, integer);
begin
  if remaining >= need then
    Result := (number + remaining - need, remaining - need)
  else
    Result := (number + remaining, 0);
end;


function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var s := operand[0].ToString;
  for var i := 1 to operand.Length - 1 do
  begin
    s := s + op[i-1] + operand[i].ToString;
  end;
  Result := integer.Parse(s);
end;


function Solve(s: string): string;
begin
  var letters := new List<char>;
  foreach var ch in s do
    if Char.IsLetter(ch) then
      letters.Add(ch);

  if letters.Count = 0 then
    Result := s.Reverse.JoinToString('')
  else
  begin
    var letterList := letters.ToArray;
    Result := letterList.Reverse.JoinToString('');
    if Char.IsLower(letterList[0]) then
      Result := Result.ToUpper
    else
      Result := Result.ToLower;
  end;
end;


function StringToMd5(text: string): string;
begin
  if text = '' then
    Result := nil
  else
    Result := System.Security.Cryptography.MD5.Create().ComputeHash(System.Text.Encoding.Default.GetBytes(text)).Aggregate('', (c, c1) -> c + c1.ToString('x2'));
end;


function GenerateIntegers(a, b: integer): array of integer;
begin
  var res := new List<integer>;
  for var num := a to b do
    if num mod 2 = 0 then
      res.Add(num);
  Result := res.ToArray;
end;
